export interface Reservation {
  id: string;
  guest: string;
}

export interface Withdrawal {
  removed: Reservation;
  remaining: Reservation[];
}

export function withdrawReservation(
  reservations: readonly Reservation[],
  id: string,
): Withdrawal {
  const seen = new Set<string>();
  for (const reservation of reservations) {
    const normalized = reservation.id.trim();
    if (normalized.length === 0 || seen.has(normalized)) {
      throw new Error("Malformed reservations");
    }
    seen.add(normalized);
  }

  const target = id.trim();
  if (target.length === 0) {
    throw new Error("Reservation not found");
  }
  const index = reservations.findIndex(
    (reservation) => reservation.id.trim() === target,
  );
  if (index < 0) {
    throw new Error("Reservation not found");
  }

  return {
    removed: { ...reservations[index] },
    remaining: reservations.filter(
      (_, candidateIndex) => candidateIndex !== index,
    ),
  };
}

