import { withdrawReservation } from "./solution";
import type { Reservation } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function assertError(action: () => unknown, message: string): void {
  try {
    action();
  } catch (error: unknown) {
    assert(error instanceof Error && error.message === message, `expected Error(${message})`);
    return;
  }
  throw new Error(`expected Error(${message})`);
}

const reservations: readonly Reservation[] = [
  { id: " one ", guest: "Ada" },
  { id: "two", guest: "Grace" },
  { id: "three", guest: "Linus" },
];
const before = JSON.stringify(reservations);
const result = withdrawReservation(reservations, "  two  ");
assert(JSON.stringify(result.removed) === JSON.stringify({ id: "two", guest: "Grace" }), "the normalized matching reservation should be removed");
assert(JSON.stringify(result.remaining) === JSON.stringify([
  { id: " one ", guest: "Ada" },
  { id: "three", guest: "Linus" },
]), "remaining reservations should preserve order and original values");
assert(JSON.stringify(reservations) === before, "input must not be mutated");
assert(result.removed !== reservations[1], "removed reservation must be copied");
assert(result.remaining[0] !== reservations[0] && result.remaining[1] !== reservations[2], "remaining reservations must be copied");
result.removed.guest = "changed";
result.remaining[0].guest = "changed";
assert(reservations[1].guest === "Grace" && reservations[0].guest === "Ada", "result mutation must not affect input objects");

assertError(() => withdrawReservation(reservations, "   "), "Reservation not found");
assertError(() => withdrawReservation(reservations, "absent"), "Reservation not found");
assert(JSON.stringify(reservations) === before, "not-found failures must not mutate input");

const blank: Reservation[] = [{ id: "ok", guest: "A" }, { id: " \t ", guest: "B" }];
const blankBefore = JSON.stringify(blank);
assertError(() => withdrawReservation(blank, "absent"), "Malformed reservations");
assert(JSON.stringify(blank) === blankBefore, "blank-ID validation failure must not mutate input");

const duplicates: Reservation[] = [{ id: "dup", guest: "A" }, { id: " dup ", guest: "B" }];
const duplicatesBefore = JSON.stringify(duplicates);
assertError(() => withdrawReservation(duplicates, "dup"), "Malformed reservations");
assert(JSON.stringify(duplicates) === duplicatesBefore, "duplicate validation failure must not mutate input");

assertError(() => withdrawReservation([], "anything"), "Reservation not found");

